# Generated by Forge scripts/export_workspace_science.py.
# fmt: off
"""Versioned native protocols and input observations, preserving the v1 record set.

Scientific structure is not execution or capture authority. An author-declared
input observation stays unverified; execution_bound requires its owning verifier.
Large source/data/configuration bytes remain in their existing custodians.
"""

from typing import Annotated, Literal

from pydantic import AwareDatetime, Field, model_validator

from .contracts import Contract, ExactReference, Identifier, Text
from .exports import ScientificExport, SourceNotice
from .records import (
    Artifact,
    Hypothesis,
    LogEntry,
    References,
    Report,
    ResearchLog,
    Result,
    Review,
    Snapshot,
    Trial,
)
from .resources import ResourceBinding, WorkspaceBinding

Seed = Annotated[int, Field(strict=True, ge=0, le=2**63 - 1)]


class ProtocolArm(Contract):
    arm_id: Identifier
    description: Text
    baseline: Annotated[bool, Field(strict=True)] = False


class ProtocolMetric(Contract):
    name: Identifier
    description: Text
    unit: Identifier
    value_kind: Literal["numeric", "qualitative"]
    direction: Literal["minimize", "maximize", "descriptive"]
    aggregation: Literal["mean", "median", "sum", "rate", "distribution", "none"]
    decision_rule: Text

    @model_validator(mode="after")
    def qualitative(self):
        if self.value_kind == "qualitative" and (
            self.direction != "descriptive" or self.aggregation != "none"
        ):
            raise ValueError("qualitative outcomes cannot claim numeric aggregation")
        return self


class SamplingPlan(Contract):
    unit: Text
    strategy: Literal["fixed_count", "sequential", "observational"]
    sample_count: Annotated[int, Field(strict=True, ge=1, le=2**63 - 1)] | None
    seed_mode: Literal["fixed", "unseeded", "unrecorded"]
    seeds: Annotated[tuple[Seed, ...], Field(max_length=10000)] = ()
    splits: References = ()
    limitations: Annotated[tuple[Text, ...], Field(max_length=256)] = ()

    @model_validator(mode="after")
    def declared_sampling(self):
        if self.strategy == "fixed_count" and self.sample_count is None:
            raise ValueError("a fixed-count plan requires its actual sample count")
        if (self.seed_mode == "fixed") != bool(self.seeds):
            raise ValueError(
                "fixed seeds must be explicit; other modes cannot invent seeds"
            )
        if len(set(self.seeds)) != len(self.seeds):
            raise ValueError("duplicate seed")
        if self.seed_mode == "unrecorded" and not self.limitations:
            raise ValueError("unrecorded seeds require an explicit limitation")
        return self


class Protocol(Contract):
    kind: Literal["protocol"] = "protocol"
    schema_version: Literal["forge.protocol.v1"] = "forge.protocol.v1"
    title: Text
    question: Text
    timing: Literal["prospective", "retrospective"]
    hypothesis: ExactReference | None = None
    comparison: Literal["controlled", "single_arm", "observational"]
    arms: Annotated[tuple[ProtocolArm, ...], Field(min_length=1, max_length=128)]
    metrics: Annotated[tuple[ProtocolMetric, ...], Field(min_length=1, max_length=256)]
    sampling: SamplingPlan
    analysis_plan: Text
    stopping_rule: Text
    deviation_policy: Text
    limitations: Annotated[tuple[Text, ...], Field(max_length=256)] = ()
    sources: References = ()

    @model_validator(mode="after")
    def declared_comparison(self):
        if len({arm.arm_id for arm in self.arms}) != len(self.arms):
            raise ValueError("duplicate protocol arm")
        if len({metric.name for metric in self.metrics}) != len(self.metrics):
            raise ValueError("duplicate protocol metric")
        if self.comparison == "controlled" and (
            len(self.arms) < 2 or not any(arm.baseline for arm in self.arms)
        ):
            raise ValueError(
                "controlled comparisons require declared arms and a baseline"
            )
        if self.comparison == "single_arm" and len(self.arms) != 1:
            raise ValueError("a single-arm protocol declares exactly one arm")
        return self


class ExperimentV2(Contract):
    kind: Literal["experiment"] = "experiment"
    schema_version: Literal["forge.experiment.v2"] = "forge.experiment.v2"
    title: Text
    specification: Text
    protocol: ExactReference
    hypothesis: ExactReference | None = None
    inputs: References = ()
    arms: Annotated[tuple[Identifier, ...], Field(min_length=1, max_length=128)]
    sources: References = ()

    @model_validator(mode="after")
    def exact_protocol(self):
        if (self.protocol.authority, self.protocol.kind) != ("forge", "protocol"):
            raise ValueError("an experiment pins an exact Forge protocol revision")
        if len(set(self.arms)) != len(self.arms):
            raise ValueError("duplicate experiment arm")
        return self


class ExecutedMaterial(Contract):
    role: Literal[
        "source",
        "generated_source",
        "dependencies",
        "environment",
        "input_data",
        "evaluator",
        "analysis",
        "configuration",
    ]
    reference: ExactReference


class ExecutedInputs(Contract):
    schema_version: Literal["forge.executed-inputs.v1"] = "forge.executed-inputs.v1"
    provenance: Literal["author_declared", "execution_bound"]
    execution_inventory: ExactReference
    observed_at: AwareDatetime
    command: Annotated[tuple[Text, ...], Field(min_length=1, max_length=256)]
    working_directory: Text
    materials: Annotated[tuple[ExecutedMaterial, ...], Field(max_length=1024)]
    seeds: Annotated[tuple[Seed, ...], Field(max_length=10000)] = ()
    evaluated_system: ExactReference | None = None
    hardware: ExactReference | None = None
    gaps: Annotated[tuple[Text, ...], Field(max_length=256)] = ()
    limitations: Annotated[tuple[Text, ...], Field(max_length=256)] = ()

    @model_validator(mode="after")
    def external_observation(self):
        if self.execution_inventory.authority not in {"orchestra", "rhodes", "mloky"}:
            raise ValueError("input inventory retains its execution owner's authority")
        identities = [
            (material.role, material.reference) for material in self.materials
        ]
        if len(set(identities)) != len(identities) or len(set(self.seeds)) != len(
            self.seeds
        ):
            raise ValueError("duplicate executed input or seed")
        return self


class TrialV2(Trial):
    schema_version: Literal["forge.trial.v2"] = "forge.trial.v2"
    protocol: ExactReference
    parent_trial: ExactReference | None = None
    execution_inputs: ExecutedInputs | None = None
    input_gaps: Annotated[tuple[Text, ...], Field(max_length=256)] = ()
    deviations: Annotated[tuple[Text, ...], Field(max_length=256)] = ()

    @model_validator(mode="after")
    def observed_inputs(self):
        if len(set(self.executed_inputs)) != len(self.executed_inputs):
            raise ValueError("duplicate executed-input reference")
        if self.parent_trial is not None and (
            self.parent_trial.authority,
            self.parent_trial.kind,
        ) != ("forge", "trial"):
            raise ValueError(
                "a successor trial links an exact retained scientific trial"
            )
        if (self.protocol.authority, self.protocol.kind) != ("forge", "protocol"):
            raise ValueError("a trial pins its experiment's exact protocol")
        if self.state == "registered" and (
            self.execution_inputs or self.executed_inputs
        ):
            raise ValueError("planned trial inputs cannot claim actual execution")
        if (
            self.state != "registered"
            and self.execution_inputs is None
            and not self.input_gaps
        ):
            raise ValueError("unavailable executed inputs require an explicit gap")
        if self.execution_inputs is not None:
            selected = tuple(
                material.reference for material in self.execution_inputs.materials
            )
            if set(self.executed_inputs) != set(selected):
                raise ValueError(
                    "executed-input links differ from the actual material selection"
                )
            if self.execution is not None and (
                self.execution_inputs.execution_inventory.authority
                != self.execution.authority
            ):
                raise ValueError("input inventory differs from the execution owner")
        return self


class ReviewV2(Review):
    schema_version: Literal["forge.review.v2"] = "forge.review.v2"


VersionedRecord = Protocol | ExperimentV2 | TrialV2 | ReviewV2


RecordV2 = Annotated[
    VersionedRecord
    | Hypothesis
    | Result
    | ResearchLog
    | LogEntry
    | Report
    | Artifact
    | Snapshot
    | ScientificExport
    | SourceNotice
    | ResourceBinding
    | WorkspaceBinding,
    Field(discriminator="kind"),
]
